// Single place that defines where benchmark data lives.
// The workflow copies the bench-results branch's data/ folder to site/data/.
// Expected layout on bench-results (assumption until the harness README defines it):
//   data/latest.json        newest registered run (schema: see site/README-data in app.js header)
//   data/runs/*.json        one file per registered run, same schema
// data/index.json (the list of run files) is generated by the Pages workflow.
window.BENCH_CONFIG = {
  DATA_DIR: "data/",
  LATEST: "data/latest.json",
  INDEX: "data/index.json",
  PREREG_VERSION_EXPECTED: "v1",
  REPO: "https://github.com/VelimirMueller/vlm-code-context-mcp"
};
